package in.anumati.platform.compliance; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/compliance") public class ComplianceController {private final ComplianceService service;public ComplianceController(ComplianceService s){service=s;} private boolean dept(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN")||x.getAuthority().equals("ROLE_DEPARTMENT_OFFICER"));} @PostMapping @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT_OFFICER')") public ComplianceResponse create(@jakarta.validation.Valid @RequestBody ComplianceRequest r,Authentication a){return service.create(r,a.getName());} @GetMapping("/business-profiles/{id}") @PreAuthorize("hasRole('APPLICANT')") public List<ComplianceResponse> business(@PathVariable UUID id,Authentication a){return service.business(id,a.getName());} @GetMapping @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT_OFFICER')") public List<ComplianceResponse> all(){return service.all();} @PostMapping("/{id}/complete") @PreAuthorize("hasAnyRole('APPLICANT','ADMIN','DEPARTMENT_OFFICER')") public ComplianceResponse complete(@PathVariable UUID id,Authentication a){return service.complete(id,a.getName(),dept(a));} }
